  const details=[el('p','',`任务：${target.taskTitle}`),el('p','',`文件：${meta.name}`),el('p','',`实际下载：${blob.size.toLocaleString()} 字节`),el('p','',`Substrate Preview.Size：${meta.expectedSize===null?'未提供':meta.expectedSize.toLocaleString()+' 字节'}`),el('p','',`HTTP Content-Length：${meta.upstreamContentLength??'未提供'}`),el('p','',`MIME：${meta.type}`),el('p','muted','已取得完整 HTTP 响应；元数据大小差异仅记录，不验证文件内部结构或最初上传的字节。')];
