async function recoverHarBatch(matches){if(busy||editing){alert('请等待同步或导入结束');return;}editing=true;let saved=0,existing=0;const errors=[];try{for(const {row,file} of matches){try{const r=await H.recoverHarFile(state,row,file,{storeFile:(id,b)=>DB.filePut(workspace+':'+id,b),loadFile:id=>DB.fileGet(workspace+':'+id),save});if(r==='saved')saved++;else existing++;}catch(e){errors.push(row.name+'：'+e.message);}}render();modal('HAR 附件恢复结果',[el('p','','已恢复 '+saved+' 个，已存在 '+existing+' 个，失败 '+errors.length+' 个。'),...errors.map(e=>el('p','muted',e))],[btn('继续补齐附件',showHarRecovery,'primary')]);}finally{editing=false;runSync();}}
