function showImportReport(c){const summary=el('p','',importSummary(c));summary.style.whiteSpace='pre-wrap';const details=el('pre','', [...c.errors,...c.attachmentErrors.map(x=>`${x.taskTitle} / ${x.stage}${x.attachmentName?' / '+x.attachmentName:''}: ${x.message}${x.requestId?' (request-id '+x.requestId+')':''}`)].join('\n'));details.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto';modal('Microsoft To Do 导入结果',[summary,el('p','muted',c.errors.length||c.attachmentTasksFailed?'部分导入失败。可再次导入任务；附件补齐请使用设置中的“仅重试待补齐附件”。':'本轮读取完成。'),...(details.textContent?[details]:[])],[btn('返回设置',settings)]);}
async function doImport(mode="full"){if(!graphToken||editing||busy)return;editing=true;const p=el('p','','读取微软任务清单…');p.style.whiteSpace='pre-wrap';modal('导入 Microsoft To Do',[p,el('p','muted','关闭窗口不取消导入；只读，不会修改微软端数据。')]);try{const counts=await G.importGraph(state,graphToken,{storeFile:(id,b)=>DB.filePut(workspace+':'+id,b),loadFile:id=>DB.fileGet(workspace+':'+id),save,mode,progress:c=>{p.textContent=(c.phase==='tasks'?'正在读取任务\n':'正在补充任务详情：'+c.detailsDone+'\n')+importSummary(c);setStatus('微软导入中：'+c.tasksScanned+' 项任务');if(c.phase==='details'&&c.detailsDone===0)render();}});importReport=counts;state.settings.msImportReport=counts;await save();graphToken=null;changed();if(dialog.open&&dialog.contains(p))showImportReport(counts);}catch(e){p.textContent='导入中断，已读取数据保留。'+e.message;graphToken=null;changed();if(!dialog.open||!dialog.contains(p))alert(p.textContent);}finally{editing=false;runSync();}}
