let lastDay=C.today();setInterval(()=>{if(lastDay!==C.today()){lastDay=C.today();render();}if(document.visibilityState==='visible')runSync();checkReminders()},15000);addEventListener('online',runSync);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')runSync()});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);
function checkReminders(){for(const t of C.all(state,'task')){const d=t.data;if(!d.completed&&d.reminder&&Date.parse(d.reminder)<=Date.now()&&Date.now()-Date.parse(d.reminder)<24*3600000){const k='reminded:'+t.id+':'+d.reminder;if(sessionStorage.getItem(k))continue;sessionStorage.setItem(k,'1');if('Notification'in window&&Notification.permission==='granted'){navigator.serviceWorker?.ready.then(r=>r.showNotification(d.title,{body:'HelloTodo 提醒',tag:k})).catch(()=>{});}else setStatus('提醒：'+d.title);}}}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});try{const outlookToken=await G.outlookCallback();if(outlookToken){const action=sessionStorage.getItem('outlook.action')||'probe-single';sessionStorage.removeItem('outlook.action');const target=JSON.parse(sessionStorage.getItem('outlook.probe.target')||'null');sessionStorage.removeItem('outlook.probe.target');if(action==='batch-attachments'){await doOutlookBatch(outlookToken);}else if(target){await doOutlookProbe(outlookToken,target);}else{modal('Outlook 授权成功',[el('p','','Exchange Online 附件读取权限已授权并保存在本机登录缓存中。'),el('p','muted','下次补齐附件时会优先静默续期，不需要重复打开授权页。')],[btn('返回设置',settings)]);}}else{graphToken=await G.callback();if(graphToken){const mode=sessionStorage.getItem('graph.importMode')||'full';sessionStorage.removeItem('graph.importMode');if(mode.startsWith('outlook-probe:')){const localTaskId=mode.slice('outlook-probe:'.length);try{const target=await G.resolveOutlookProbeTarget(state,graphToken,localTaskId);sessionStorage.setItem('outlook.probe.target',JSON.stringify(target));graphToken=null;await G.signInOutlook('probe-single');}catch(e){graphToken=null;sessionStorage.removeItem('outlook.probe.target');modal('Graph 任务定位失败',[el('p','',e.message),el('p','muted','本次尚未进行 Outlook 授权。')],[btn('返回设置',settings)]);}}else await doImport(mode);}}}catch(e){sessionStorage.removeItem('outlook.probe.target');sessionStorage.removeItem('outlook.action');alert('Microsoft 登录 / 附件测试失败：'+e.message);}runSync();

if(['#migration','#migration-attachments'].includes(location.hash)){const retry=location.hash==='#migration-attachments';history.replaceState(null,'',location.pathname+location.search);if(!dialog.open){settings();const target=[...dialog.querySelectorAll('button')].find(b=>b.textContent===(retry?'仅重试待补齐附件':'Microsoft 登录并授权导入'));if(target&&!target.disabled)target.focus();}}

async function accountBootstrap(){
 accountProfile=await DB.read('profile:'+workspace)||null;
 const incoming=await DB.read('account.session');
 if(incoming?.token&&incoming?.account){
  if(busy||editing){setTimeout(()=>accountBootstrap().catch(error=>setStatus(error.message)),500);return;}
  await connect(incoming.token,incoming.account);await DB.write('account.session',null);return;
 }
 if(key){if(accountProfile){const response=await fetch('/api/auth/me',{headers:{Authorization:'Bearer '+key}});if(response.status===401)setStatus('登录已过期，请在设置中重新登录；离线修改已保留。');}return;}
 if(await DB.read('welcome.seen'))return;
 if(location.search.includes('code='))return;
 let config={enabled:false,providers:[]};try{const response=await fetch('/api/auth/config');if(response.ok)config=await response.json();}catch{}
 if(dialog.open)return;
 const logo=el('img','welcome-logo');logo.src='icon.svg';logo.alt='HelloTodo';logo.dataset.appLogo='';
 const choices=append(el('div','welcome-actions'),btn('注册或登录',()=>location.assign('/account.html'),'primary'));
 for(const provider of config.providers||[]){const button=btn('使用 '+provider.name+' 登录',()=>location.assign('/account.html?provider='+provider.id));button.disabled=!provider.enabled;if(!provider.enabled)button.title='发布者尚未配置此登录方式';choices.append(button);}
 modal('欢迎使用 HelloTodo',[logo,el('p','','登录后，在手机、电脑和网页间同步任务。'),...(!config.enabled?[el('p','muted','账号服务尚未配置，可以先使用本地模式。')]:[]),choices],[btn('暂不登录，使用本地模式',async()=>{await DB.write('welcome.seen',true);dialog.close();})]);
 theme();
}
accountBootstrap().catch(error=>setStatus('账号连接未完成：'+error.message));
